const CONDITIONS = {
  0: 'despejado',
  1: 'mayormente despejado',
  2: 'parcialmente nublado',
  3: 'nublado',
  45: 'con niebla',
  48: 'con niebla',
  51: 'con llovizna ligera',
  53: 'con llovizna',
  55: 'con llovizna intensa',
  56: 'con llovizna helada',
  57: 'con llovizna helada',
  61: 'con lluvia ligera',
  63: 'con lluvia',
  65: 'con lluvia fuerte',
  66: 'con lluvia helada',
  67: 'con lluvia helada',
  71: 'con nieve ligera',
  73: 'con nieve',
  75: 'con nieve fuerte',
  77: 'con granizo fino',
  80: 'con chubascos ligeros',
  81: 'con chubascos',
  82: 'con chubascos fuertes',
  85: 'con chubascos de nieve',
  86: 'con chubascos de nieve',
  95: 'con tormenta',
  96: 'con tormenta y granizo',
  99: 'con tormenta y granizo fuerte',
};
const DAY_NAMES = ['Hoy', 'Mañana', 'Pasado mañana'];

const describe = (code) => CONDITIONS[code] ?? 'con condiciones variables';
const round = (value) => Math.round(value);

const requested = ($('Webhook').first().json.body?.text || '').trim() || 'Monterrey';
const place = $('Geocodificar').first().json.results?.[0];
const location = place
  ? [place.name, place.admin1, place.country].filter(Boolean).join(', ')
  : 'Monterrey, Nuevo León, México';
const { current, daily } = $input.first().json;

const days = daily.time.map((date, index) => ({
  date,
  condition: describe(daily.weather_code[index]),
  min: round(daily.temperature_2m_min[index]),
  max: round(daily.temperature_2m_max[index]),
  rain_probability: daily.precipitation_probability_max[index],
}));

const notFound = place ? '' : `No encontré «${requested}»; te doy el de Monterrey. `;
const now = `Ahora en ${location}: ${round(current.temperature_2m)} °C, sensación de ${round(current.apparent_temperature)} °C, ${describe(current.weather_code)}, humedad de ${current.relative_humidity_2m}% y viento de ${round(current.wind_speed_10m)} km/h.`;
const forecast = days
  .map((day, index) => `${DAY_NAMES[index]}: ${day.condition}, entre ${day.min} y ${day.max} °C, ${day.rain_probability}% de probabilidad de lluvia.`)
  .join(' ');

return [{
  json: {
    summary: `${notFound}${now} ${forecast} Fuente: Open-Meteo.`,
    location,
    current: {
      temperature: current.temperature_2m,
      feels_like: current.apparent_temperature,
      humidity: current.relative_humidity_2m,
      wind_kmh: current.wind_speed_10m,
      condition: describe(current.weather_code),
      time: current.time,
    },
    days,
  },
}];
